package com.foodflow.review.client;import org.springframework.cloud.openfeign.FeignClient;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.PathVariable;import java.util.Map;import java.util.UUID;
@FeignClient(name="order-service",url="${foodflow.order.url:}",configuration=com.foodflow.review.config.FeignConfig.class) public interface OrderClient{@GetMapping("/api/orders/internal/{id}/review-check") Map<String,Object> reviewCheck(@PathVariable UUID id);}
